import {ports,cruises} from './data.js';
import {registerPort} from './ncl.js';
import {query} from './celebrity-query.js';
export const feed={loading:false,error:null,page:0,hasMore:false,totalItineraries:0,loadedItineraries:0,checkedAt:null};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const aliases={ROM:'CIV',REG:'MSN',KAT:'KAK',POA:'BAR',ATH:'PIR',ADB:'KUS',ALN:'AES',BFT:'BEL',BLQ:'RAV',CHQ:'CHA',FLR:'LIV',GLA:'GRK',KTR:'KOT',LPL:'LIVP',LSP:'SPE',LWK:'LER',OLN:'OLD',OPO:'LXO',ORK:'COB',SNO:'SAL',STH:'SOU',SVG:'STA',ZWD:'WAR'};
const extra={AAR:[56.15,10.22],AGP:[36.71,-4.42],HYD:[37.35,23.46],JCA:[43.55,7.01],PTF:[44.3,9.21]};
export function officialImage(path){if(!path||typeof path!=='string'||!/^\/(celebrity\/|content\/dam\/celebrity\/)/.test(path))return null;const p=path.replace(/^\/content\/dam/,'');const u=new URL('https://assets.dm.rccl.com/is/image/RoyalCaribbeanCruises'+p);u.searchParams.set('wid','960');u.searchParams.set('qlt','85');return u.href;}
function portId(p){const code=aliases[p.code]||p.code;if(extra[p.code]){const id='cel-'+p.code;if(!ports.some(p=>p.id===id)){const [lat,lon]=extra[p.code];ports.push({id,name:escape(p.name),country:'',lat,lon});}return id;}return registerPort({code,title:p.name});}
export function normalizeCruises(items,state,observedAt){const output=[];for(const item of items){const it=item.masterSailing?.itinerary,nights=it?.totalNights;if(!it||!Number.isInteger(nights)||nights<1||nights>100||!Array.isArray(it.days))continue;const stops=[];for(const d of it.days.slice().sort((a,b)=>a.number-b.number))for(const p of d.ports||[]){if(!/^[A-Z0-9]{2,8}$/.test(p.port?.code)||p.port.code==='ASE'||p.activity==='CRUISING')continue;const id=portId(p.port);if(stops.at(-1)?.id!==id)stops.push({id,name:escape(p.port.name),day:d.number,image:officialImage(p.port.media?.images?.[0]?.path)});}if(!stops.length)continue;
 for(const s of item.sailings||[]){const price=s.lowestStateroomClassPrice?.price,date=s.startDate;if(price?.currency?.code!=='CAD'||!Number.isFinite(price.value)||price.value<=0||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^[-\w]+$/.test(s.id))continue;const endDate=new Date(Date.parse(date+'T12:00:00Z')+nights*864e5).toISOString().slice(0,10);if(date<state.start||endDate>state.end)continue;let url;try{url=new URL(s.productViewLink,'https://www.celebritycruises.com/ca/');}catch{continue;}if(url.origin!=='https://www.celebritycruises.com'||!url.pathname.startsWith('/ca/itinerary/'))continue;url.searchParams.set('country','CAN');const mapped=stops.map(p=>ports.find(x=>x.id===p.id));const region=mapped.some(p=>p.lat>=49)?'north':stops.some(p=>['athens','santorini','mykonos','RHO','CHA'].includes(p.id))?'greek':'west';
 output.push({id:'celebrity-'+s.id,title:escape(it.name),company:'Celebrity Cruises',provider:'celebrity',ship:escape(it.ship?.name),date,endDate,nights,price:Math.ceil(price.value),currency:'CAD',cabin:'Meilleur tarif affiché',taxesIncluded:s.taxesAndFeesIncluded===true,ports:stops.map(p=>p.id),stops:stops.map(p=>({...p})),region,image:officialImage(it.media?.images?.[0]?.path),sourceUrl:url.href,observedAt,live:true});
 }}return output;}
let controller,version=0;const cache=new Map();
export function cancel(){controller?.abort();version++;feed.loading=false;}
export async function loadCruises(state,append=false,onUpdate=()=>{}){controller?.abort();controller=new AbortController();const signal=controller.signal,run=++version;feed.loading=true;feed.error=null;if(!append){feed.page=0;feed.loadedItineraries=0;}onUpdate();try{
 if(!/^\d{4}-\d{2}-\d{2}$/.test(state.start)||!/^\d{4}-\d{2}-\d{2}$/.test(state.end)||state.start>state.end)throw Error('Choisissez une période valide.');
 const variables={filters:`destination:EUROP|startDate:${state.start}~${state.end}|type:CRUISE|adults:2`,sort:{by:'SAILDATE',order:'ASC'},pagination:{count:12,skip:feed.page*12}};const key=JSON.stringify(variables),now=Date.now();let stored=cache.get(key);if(!stored||now-stored.time>300000){const response=await fetch('https://www.celebritycruises.com/graph',{method:'POST',credentials:'omit',signal,headers:{'Content-Type':'application/json',brand:'C',Country:'CAN',Currency:'CAD',Language:'en',Office:'MIA'},body:JSON.stringify({query,variables,operationName:'CruiseSearch'})});if(!response.ok)throw Error('La source Celebrity est temporairement indisponible.');const raw=await response.json();const value=raw.data?.cruiseSearch?.results;if(raw.errors?.length||!Array.isArray(value?.cruises)||!Number.isFinite(value.total))throw Error('Le format de la source Celebrity a changé.');stored={value,time:now};cache.set(key,stored);if(cache.size>50)cache.delete(cache.keys().next().value);}
 if(run!==version)return;const existing=new Set(cruises.map(c=>c.id));for(const c of normalizeCruises(stored.value.cruises,state,new Date(stored.time).toISOString()))if(!existing.has(c.id)){cruises.push(c);existing.add(c.id);}feed.totalItineraries=stored.value.total;feed.loadedItineraries+=stored.value.cruises.length;feed.hasMore=(feed.page+1)*12<stored.value.total;feed.page++;feed.checkedAt=new Date(stored.time).toISOString();
 }catch(e){if(run===version&&!signal.aborted){feed.error='Celebrity : '+e.message;feed.hasMore=false;}}finally{if(run===version){feed.loading=false;onUpdate();}}}
